"""TED Bodrum Koleji çalışma kâğıdı üretici (yalnızca Python standart kütüphanesi).

Okulun şablonu (header'da logo, A4, Calibri, alt bilgi) bu dosyanın içine gömülüdür.
Biçimi bu kod belirler; çağıran yalnızca İÇERİĞİ bir sözlük (spec) olarak verir.

KULLANIM (Gemini kod ortamında):
    import glob; exec(open(glob.glob('**/*ws_olustur*', recursive=True)[0], encoding='utf-8').read())
    yol = olustur(spec)          # -> 'fen_ws_<konu>_vs1.docx'

SPEC ÖRNEĞİ: ORNEK_SPEC değişkenine bakın. Alanlar:
  etkinlik_adi, egitim_yili, sinif ("5. Sınıf"), donem ("1. Dönem"), hafta ("12. Hafta"),
  unite ("3. Ünite / Canlıların Yapısına Yolculuk"), sube ("5/A-B"), toplam_puan (int),
  amac_etiketi (varsayılan "Gözlem Amacı"), amac, malzemeler (liste), konu (dosya adı için kısa, ör. "hucre"),
  bolumler: [{"baslik": "Ön Bilgi", "ogeler": [OGE, ...]}, ...]
OGE türleri (numaralar otomatik verilir: 1.1, 1.2 ...):
  {"tur": "yonerge", "metin": "..."}                                   # kutusuz adım
  {"tur": "soru", "metin": "...", "puan": 10, "kutu": "kucuk|orta|buyuk"}  # altında cevap kutusu
  {"tur": "tablo", "metin": "... (isteğe bağlı yönerge)", "puan": 10 (isteğe bağlı),
   "tablo_adi": "Gözlem Kayıt Tablosu", "basliklar": ["Kısım", "Görevi"],
   "satirlar": [["Tuğla", ""], ["Duvar", ""]]  veya  "bos_satir": 5,
   "satir_yuksekligi": "tablo|kucuk|orta|buyuk" (varsayılan "tablo" = 1,4 cm),
   "genislikler": [1, 2] (isteğe bağlı oran)}
Metinde __altı çizili__ yazımı vurgu için alt çizgi üretir.
Puanların toplamı toplam_puan'a eşit değilse ValueError verir.
"""
import base64, datetime, io, re, zipfile
from xml.sax.saxutils import escape

SABLON_B64 = ""

TW = {"kucuk": 851, "orta": 1985, "buyuk": 3969, "tablo": 794}  # twip: 1,5 / 3,5 / 7 / 1,4 cm
TAM = 9070  # A4 - 2 x 2,5 cm
BASLIK_DOLGU = "D9E2F3"


def _run(text, b=False, u=False, sz=22):
    rpr = '<w:rFonts w:ascii="Calibri" w:hAnsi="Calibri" w:cs="Calibri"/>'
    rpr += ("<w:b/><w:bCs/>" if b else "") + ('<w:u w:val="single"/>' if u else "")
    rpr += f'<w:sz w:val="{sz}"/><w:szCs w:val="{sz}"/>'
    return f'<w:r><w:rPr>{rpr}</w:rPr><w:t xml:space="preserve">{escape(text)}</w:t></w:r>'


def _rich(text, b=False, sz=22):
    """'__x__' -> altı çizili."""
    parts = re.split(r"__(.+?)__", text)
    return "".join(_run(t, b=b, u=bool(i % 2), sz=sz) for i, t in enumerate(parts) if t)


def _p(runs, jc="both", line=360, after=120, keep=False):
    ppr = f'<w:spacing w:before="0" w:after="{after}" w:line="{line}" w:lineRule="auto"/>'
    ppr += "<w:keepNext/>" if keep else ""
    ppr += f'<w:jc w:val="{jc}"/>'
    return f"<w:p><w:pPr>{ppr}</w:pPr>{runs}</w:p>"


def _tp(text, b=False):  # tablo içi: Calibri 11, 1,15, sola yaslı
    return _p(_rich(text, b=b), jc="left", line=276, after=0)


def _tablo(rows, widths, heights, header=False):
    brd = "".join(f'<w:{s} w:val="single" w:sz="6" w:space="0" w:color="000000"/>'
                  for s in ("top", "left", "bottom", "right", "insideH", "insideV"))
    x = (f'<w:tbl><w:tblPr><w:tblW w:w="{sum(widths)}" w:type="dxa"/><w:tblBorders>{brd}</w:tblBorders>'
         '<w:tblLayout w:type="fixed"/><w:tblCellMar><w:left w:w="108" w:type="dxa"/>'
         '<w:right w:w="108" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>'
         + "".join(f'<w:gridCol w:w="{w}"/>' for w in widths) + "</w:tblGrid>")
    for ri, row in enumerate(rows):
        h = heights[ri]
        trpr = "<w:cantSplit/>" + (f'<w:tblHeader/>' if header and ri == 0 else "")
        trpr += f'<w:trHeight w:val="{h}" w:hRule="atLeast"/>' if h else ""
        x += f"<w:tr><w:trPr>{trpr}</w:trPr>"
        for ci, c in enumerate(row):
            shd = f'<w:shd w:val="clear" w:color="auto" w:fill="{BASLIK_DOLGU}"/>' if header and ri == 0 else ""
            x += f'<w:tc><w:tcPr><w:tcW w:w="{widths[ci]}" w:type="dxa"/>{shd}</w:tcPr>{c}</w:tc>'
        x += "</w:tr>"
    return x + "</w:tbl>"


def _bosluk():
    return _p("", after=0)


def _genislik(n, oran=None):
    oran = oran or [1] * n
    if len(oran) != n:
        raise ValueError("genislikler sayısı sütun sayısına eşit olmalı")
    ws = [int(TAM * o / sum(oran)) for o in oran]
    ws[-1] += TAM - sum(ws)
    return ws


def _govde(spec):
    g, puanlar, tablo_no = [], [], 0
    yil = spec.get("egitim_yili", "2025-2026")
    g.append(_p(_run("Fen Bilimleri Performans Çalışması: ", b=True, sz=24) + _run(spec["etkinlik_adi"], b=True, sz=24),
                jc="center", after=60))
    alt = " · ".join(x for x in (f"{yil} Eğitim Öğretim Yılı", spec.get("sinif"), spec.get("donem"), spec.get("hafta")) if x)
    g.append(_p(_run(alt), jc="center", after=200))
    g.append(_tablo([
        [_tp("Ünite/Tema/Konu:", True), _tp(spec["unite"]), _tp("Sınıf:", True), _tp(spec["sube"])],
        [_tp("Adı-Soyadı:", True), _tp(""), _tp("Tarih:", True), _tp("")],
        [_tp("No:", True), _tp(""), _tp("Puan:", True), _tp(f"___ / {spec['toplam_puan']}")],
    ], [2150, 3650, 1100, 2170], [567, 567, 567]))
    g.append(_bosluk())
    g.append(_p(_run(f"{spec.get('amac_etiketi', 'Gözlem Amacı')}: ", b=True) + _rich(spec["amac"])))
    if spec.get("malzemeler"):
        g.append(_p(_run("Malzemeler: ", b=True) + _run(" • ".join(spec["malzemeler"]))))
    for bi, bol in enumerate(spec["bolumler"], 1):
        g.append(_p(_run(f"{bi}. {bol['baslik']}", b=True), jc="left", keep=True))
        for oi, o in enumerate(bol["ogeler"], 1):
            tur, no = o["tur"], f"{bi}.{oi}. "
            puan = o.get("puan")
            if puan is not None:
                puanlar.append(int(puan))
            ek = _run(f" ({puan} puan)") if puan is not None else ""
            if o.get("metin"):
                g.append(_p(_run(no, b=True) + _rich(o["metin"]) + ek, keep=tur != "yonerge"))
            if tur == "yonerge":
                continue
            if tur == "soru":
                g.append(_tablo([[_tp("")]], [TAM], [TW[o.get("kutu", "orta")]]))
                g.append(_bosluk())
            elif tur == "tablo":
                bas = o["basliklar"]
                satirlar = o.get("satirlar") or [[""] * len(bas) for _ in range(int(o.get("bos_satir", 3)))]
                if any(len(s) != len(bas) for s in satirlar):
                    raise ValueError(f"{no}tablosunda her satır {len(bas)} hücre olmalı")
                h = TW[o.get("satir_yuksekligi", "tablo")]
                rows = [[_tp(c, True) for c in bas]] + [[_tp(c) for c in s] for s in satirlar]
                g.append(_tablo(rows, _genislik(len(bas), o.get("genislikler")), [None] + [h] * len(satirlar), header=True))
                tablo_no += 1
                g.append(_p(_run(f"Tablo {tablo_no}. {o.get('tablo_adi', '')}".rstrip(), b=True), jc="left", line=276, after=200))
            else:
                raise ValueError(f"bilinmeyen öğe türü: {tur}")
    if sum(puanlar) != int(spec["toplam_puan"]):
        raise ValueError(f"puan toplamı {sum(puanlar)}, toplam_puan {spec['toplam_puan']} olmalı")
    return "".join(g)


def _konu(s):
    tr = str.maketrans("çğıöşüÇĞİÖŞÜ ", "cgiosuCGIOSU_")
    return re.sub(r"[^a-z0-9_-]", "", s.translate(tr).lower()) or "etkinlik"


def olustur(spec, cikti=None):
    konu = _konu(spec.get("konu") or spec["etkinlik_adi"])
    ay_yil = spec.get("ay_yil") or datetime.date.today().strftime("%m/%Y")
    cikti = cikti or f"fen_ws_{konu}_vs1.docx"
    zin = zipfile.ZipFile(io.BytesIO(base64.b64decode(SABLON_B64)))
    doc = zin.read("word/document.xml").decode("utf8")
    bas = doc[: doc.index("<w:body>") + len("<w:body>")]
    sect = re.search(r"<w:sectPr.*?</w:sectPr>", doc, re.S).group(0)
    yeni = bas + _govde(spec) + sect + "</w:body></w:document>"
    with zipfile.ZipFile(cikti, "w", zipfile.ZIP_DEFLATED) as zout:
        for item in zin.infolist():
            data = zin.read(item.filename)
            if item.filename == "word/document.xml":
                data = yeni.encode("utf8")
            elif item.filename == "word/footer2.xml":
                data = data.replace(b"fen_ws_[konu]_vs1_[AA/YYYY]", f"fen_ws_{konu}_vs1_{ay_yil}".encode())
            zout.writestr(item, data)
    return cikti


ORNEK_SPEC = {
    "etkinlik_adi": "Hücreden Organizmaya", "egitim_yili": "2025-2026", "sinif": "5. Sınıf",
    "donem": "1. Dönem", "hafta": "12. Hafta", "unite": "3. Ünite / Canlıların Yapısına Yolculuk",
    "sube": "5/A-B", "toplam_puan": 50, "konu": "hucre",
    "amac": "Hücreden organizmaya uzanan yapılar arasında nasıl bir __hiyerarşik ilişki__ vardır?",
    "malzemeler": ["Renkli karton", "Makas", "Yapıştırıcı"],
    "bolumler": [
        {"baslik": "Ön Bilgi", "ogeler": [
            {"tur": "soru", "metin": "Tuğlalar ile hücreler arasında nasıl bir benzerlik kurabilirsiniz?", "puan": 10, "kutu": "kucuk"}]},
        {"baslik": "İnceleme / Gözlem", "ogeler": [
            {"tur": "yonerge", "metin": "Kartonlardan farklı büyüklükte beş şekil kesiniz."},
            {"tur": "tablo", "metin": "Tabloyu küçükten büyüğe doldurunuz.", "puan": 15, "tablo_adi": "Hiyerarşi Tablosu",
             "basliklar": ["Sıra", "Yapı", "Günlük Hayat Benzetmesi"], "genislikler": [1, 2, 3],
             "satirlar": [["1", "", ""], ["2", "", ""], ["3", "", ""], ["4", "", ""], ["5", "", ""]]},
            {"tur": "soru", "metin": "Kestiğiniz şekilleri sıraya göre yapıştırınız.", "puan": 10, "kutu": "buyuk"}]},
        {"baslik": "Yorumlama ve Sonuç", "ogeler": [
            {"tur": "soru", "metin": "Bir organ görevini yapamazsa organizma nasıl etkilenir?", "puan": 15, "kutu": "orta"}]},
    ],
}

if __name__ == "__main__":  # öz-denetim
    import os, tempfile
    yol = olustur(ORNEK_SPEC, os.path.join(tempfile.gettempdir(), "ws_test.docx"))
    z = zipfile.ZipFile(yol)
    d, f, h = (z.read(n).decode() for n in ("word/document.xml", "word/footer2.xml", "word/header1.xml"))
    assert "Hücreden Organizmaya" in d and "<w:drawing>" in h and 'w:w="11906"' in d
    assert "fen_ws_hucre_vs1_" in f and "[konu]" not in f
    assert d.count('w:val="3969"') == 1 and d.count('w:val="851"') == 1 and d.count('w:val="1985"') == 1
    assert "Tablo 1. Hiyerarşi Tablosu" in d and "2.2. " in d and "(15 puan)" in d
    try:
        olustur(dict(ORNEK_SPEC, toplam_puan=40), os.path.join(tempfile.gettempdir(), "x.docx")); raise SystemExit("puan kontrolü çalışmadı")
    except ValueError:
        pass
    print("öz-denetim tamam:", yol)
